413: foe(){let best=null,bs=1e9;for(const e of G.ents){if(e.side===this.side||e.hp<=0)continue;const dx=e.x-this.x,dy=e.y-this.y;const d2=dx*dx+dy*dy;if(d2>this.rng*this.rng)continue;const w=(e.role==="tank")?d2*.64:d2;if(w<bs){bs=w;best=e;}}return best;}
414: allyHurt(){let best=null,bl=1;for(const e of G.ents){if(e.side!==this.side||e===this||e.hp<=0)continue;const f=e.hp/e.max;if(f<.92&&f<bl){const dx=e.x-this.x,dy=e.y-this.y;if(dx*dx+dy*dy<=(this.rng+60)*(this.rng+60)){bl=f;best=e;}}}return best;}
415: step(dx,dy){for(const e of G.ents){if(e===this||e.hp<=0)continue;const same=e.side===this.side;const ox=this.x-e.x,oy=this.y-e.y;const d2=ox*ox+oy*oy;const rr=same?38:30;if(d2<rr*rr&&d2>.01){const d=Math.sqrt(d2);dx+=ox/d*(same?46:32)*.016;dy+=oy/d*(same?46:32)*.016;}}let nx=this.x+dx,ny=this.y+dy;nx=Math.max(30,Math.min(CFG.AW-30,nx));ny=Math.max(36,Math.min(CFG.AH-36,ny));this.moved+=Math.abs(dx)+Math.abs(dy)*.5;this.vx=dx;this.vy=dy;this.x=nx;this.y=ny;}
