.menu-head{padding:14px 14px 12px;display:flex;justify-content:space-between;align-items:center;background:linear-gradient(180deg,rgba(18,12,35,.92),rgba(18,12,35,.72));border-bottom:1px solid rgba(255,255,255,.1);backdrop-filter:blur(8px);z-index:5;animation:drop .4s ease;box-shadow:0 8px 24px rgba(0,0,0,.18)}
@keyframes drop{from{transform:translateY(-100%)} }
.logo{font-size:22px;font-weight:900;background:linear-gradient(180deg,#ffe8ff 0%,#f1bbff 18%,#d85dff 52%,#a736ff 100%);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 0 12px rgba(214,51,255,.6));letter-spacing:.5px}
.logo small{display:block;font-size:9px;color:#b9b0da;letter-spacing:4px;-webkit-text-fill-color:#b9b0da;margin-top:2px}
.hrow{display:flex;gap:8px;align-items:center}
.coin{background:linear-gradient(180deg,#4a3300,#1d1700);border:1px solid rgba(255,214,64,.9);color:var(--gold);border-radius:20px;padding:7px 13px;font-weight:900;font-size:13px;box-shadow:0 0 12px rgba(255,235,59,.2)}
.tro{background:linear-gradient(180deg,#430b4f,#1d051d);border:1px solid rgba(214,51,255,.85);color:#f8d9ff;border-radius:20px;padding:7px 13px;font-weight:900;font-size:13px;box-shadow:0 0 12px rgba(214,51,255,.2)}
.ibtn{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);color:#fff;border-radius:12px;padding:7px 11px;font-size:15px;cursor:pointer;transition:transform .1s}
.ibtn:active{transform:scale(.9)}
.mbody{flex:1;overflow-y:auto;padding:12px 12px 16px;-webkit-overflow-scrolling:touch}
.tabs{display:flex;gap:6px;padding:6px;background:rgba(19,23,35,.7);border:1px solid rgba(255,255,255,.08);border-radius:18px;z-index:5;box-shadow:inset 0 0 18px rgba(0,0,0,.3)}
.tab{flex:1;background:transparent;border:none;color:#a8b0d8;border-radius:12px;padding:8px 4px;font-size:18px;cursor:pointer;text-align:center;font-weight:900;transition:all .15s ease}
.tab span{display:block;font-size:9px;font-weight:700;letter-spacing:.8px}
.tab.on{background:linear-gradient(180deg,#2a1f4e,#191c2d);color:#fff;border:1px solid rgba(214,51,255,.7);box-shadow:0 8px 16px rgba(214,51,255,.16)}
.msec{display:none}
.msec.on{display:block;animation:fadeUp .3s ease}
.deckbox.sticky{position:sticky;top:0;z-index:4}
.fchips{display:flex;gap:6px;margin:4px 0 8px;flex-wrap:wrap}
.fchip{background:#151524;border:1px solid #3d3d5c;color:#ccc;border-radius:16px;padding:5px 11px;font-size:11px;font-weight:800;cursor:pointer}
.fchip.on{border-color:var(--primary);color:#fff;background:#1d3a1f}
.gbadge{position:absolute;bottom:4px;right:4px;font-size:14px;background:rgba(0,0,0,.6);border-radius:50%;width:22px;height:22px;display:flex;align-items:center;justify-content:center}
.grow{display:flex;gap:4px;margin-top:6px}
.gbtn{flex:1;background:#1a1a2e;border:1px solid #55556e;color:#ffd54f;border-radius:8px;padding:6px 2px;font-size:10px;font-weight:900;cursor:pointer}
.ucard .gbadge{bottom:auto;top:4px;right:4px}
/* Arena banner */
.arena{position:relative;border-radius:20px;padding:18px 16px 14px;overflow:hidden;margin:12px 0 14px;border:1px solid rgba(255,223,112,.7);background:linear-gradient(135deg,#3a1d69 0%,#4d1254 35%,#6f2c1a 100%);box-shadow:0 10px 24px rgba(83,36,125,.45), inset 0 1px 0 rgba(255,255,255,.16);animation:fadeUp .45s ease}
.arena::before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 20% 20%,rgba(255,255,255,.3),transparent 32%),radial-gradient(circle at 80% 10%,rgba(255,215,120,.28),transparent 22%);pointer-events:none}
.arena::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 30%,rgba(255,255,255,.12) 50%,transparent 70%);animation:shine 3.5s infinite}
@keyframes shine{from{transform:translateX(-110%)}to{transform:translateX(110%)}}
.arena .an{position:relative;z-index:1;font-size:20px;font-weight:900;text-shadow:0 2px 0 #000;letter-spacing:.5px}
.arena .ap{position:relative;z-index:1;font-size:11px;color:#ffe9a8;font-weight:700;margin-top:6px}
.abar{position:relative;z-index:1;height:10px;background:rgba(8,11,18,.6);border-radius:999px;margin-top:10px;overflow:hidden;border:1px solid rgba(255,255,255,.32)}
.abar i{display:block;height:100%;background:linear-gradient(90deg,#ffd95c,#ffb000,#ff8a00);border-radius:999px;transition:width .5s;box-shadow:0 0 10px rgba(255,176,0,.5)}
@keyframes fadeUp{from{opacity:0;transform:translateY(14px)}}
/* mode cards */
.modes{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:0 0 8px}
.mode{border:1px solid rgba(255,255,255,.12);background:linear-gradient(180deg,#21263a,#111827 48%,#0c111b);border-radius:18px;padding:16px 8px 12px;color:#fff;cursor:pointer;text-align:center;animation:fadeUp .5s ease;transition:transform .12s,border-color .12s,box-shadow .12s;box-shadow:inset 0 1px 0 rgba(255,255,255,.08)}
.mode:active{transform:scale(.96)}
.mode b{display:block;font-size:14px;margin-top:7px;font-weight:900}.mode span{font-size:10px;color:#9ab0d0;letter-spacing:.7px}
.mode .mi{font-size:32px;filter:drop-shadow(0 5px 6px rgba(0,0,0,.5))}
.mode.hot{border-color:rgba(255,213,79,.8);background:linear-gradient(180deg,#2f2946,#181f2d 50%,#121a22);box-shadow:0 0 20px rgba(255,213,79,.18),inset 0 1px 0 rgba(255,255,255,.15)}
.diffrow{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:10px 0}
.diff{border:1px solid rgba(255,255,255,.12);background:rgba(18,22,31,.85);color:#dfe6ff;border-radius:12px;padding:10px 8px;font-weight:800;font-size:12px;cursor:pointer;text-align:center;transition:all .15s ease}
.diff.on{border-color:rgba(76,175,80,.8);color:#fff;background:linear-gradient(180deg,#214329,#0f1d14);box-shadow:0 0 12px rgba(76,175,80,.3)}
.hist{background:rgba(16,19,28,.75);border:1px solid rgba(255,255,255,.08);border-radius:14px;padding:12px 14px;margin-top:12px;color:#dfe6ff;font-size:11px;line-height:1.6;box-shadow:inset 0 1px 0 rgba(255,255,255,.05)}

