.stitle{color:#fff;font-weight:1000;text-shadow:0 2px 2px rgba(21,51,47,.65);letter-spacing:.5px}
.deckbox{background:linear-gradient(180deg,rgba(30,75,92,.88),rgba(20,54,67,.94));border:2px solid #a9d8e6;border-radius:13px;box-shadow:0 4px 0 #234b60}
.dslot{border-radius:9px}.dslot.full{border-color:#9cda6b;background:linear-gradient(180deg,#4c814b,#245032)}
.dadd{border-color:#d6e7ef;color:#fff;background:rgba(255,255,255,.12);border-radius:9px}
.hist{background:rgba(18,50,59,.72);border:1px solid rgba(226,247,244,.35);color:#f2fffc}
.chest{border-radius:10px;box-shadow:0 3px 0 rgba(32,44,55,.35)}
